#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<pair<int,int>> items(n);
    int sumAtk = 0;
    for (int i = 0; i < n; ++i) {
        int a, c;
        cin >> a >> c;
        items[i] = {a, c};
        sumAtk += a;
    }

    const int INF = 1e9 + 10;
    vector<int> dp(sumAtk+1, INF);
    dp[0] = 0;
    int cur = 0;
    for (auto [a, c] : items) {
        cur += a;
        for (int j = cur; j >= a; --j) {
            dp[j] = min(dp[j], dp[j-a]+c);
        }
    }

    int ans = 0;
    for (int j = 0; j <= sumAtk; ++j) {
        if (dp[j] <= m) ans = j;
    }
    cout << ans << '\n';
    return 0;
}
